"""Background music generated by FFmpeg itself: no third-party licence, different every video (mood + seed)."""
import subprocess

MOODS = {  # base Hz, tremolo Hz, pulse depth, noise level
    "dread": (55.0, 0.08, 0.0, 0.035), "uneasy": (62.0, 0.13, 0.0, 0.05),
    "hollow": (41.0, 0.06, 0.0, 0.06), "pulse": (49.0, 0.10, 0.45, 0.03),
}


def ambient_args(duration, out, mood="dread", seed=0, ffmpeg="ffmpeg"):
    base, trem, pulse, noise = MOODS.get(mood, MOODS["dread"]); f = base * (1 + 0.035 * (seed % 7))
    expr = (f"(0.34*sin(2*PI*{f:.2f}*t)+0.22*sin(2*PI*{f * 1.498:.2f}*t)+0.10*sin(2*PI*{f * 2.01:.2f}*t))"
            f"*(0.65+0.35*sin(2*PI*{trem}*t))*(1-{pulse}*abs(sin(PI*1.1*t)))")
    fade_out = max(0.0, duration - 2.0)
    graph = (f"[1:a]lowpass=f=700[n];[0:a][n]amix=inputs=2:normalize=0,lowpass=f=1400,"
             f"afade=t=in:d=1.5,afade=t=out:st={fade_out:.2f}:d=2[a]")
    return [ffmpeg, "-y", "-loglevel", "error", "-f", "lavfi", "-i", f"aevalsrc={expr}:s=44100:d={duration:.2f}",
            "-f", "lavfi", "-i", f"anoisesrc=d={duration:.2f}:c=pink:a={noise}:r=44100:s={seed + 1}",
            "-filter_complex", graph, "-map", "[a]", "-ac", "2", "-ar", "44100", str(out)]


def make_ambient(duration, out, mood="dread", seed=0, runner=subprocess.run):
    r = runner(ambient_args(duration, out, mood, seed), capture_output=True, text=True)
    if r.returncode != 0: raise RuntimeError("music generation failed: " + (r.stderr or "")[-300:])
